<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\Pilot; use Illuminate\Http\Request;
class PilotController extends Controller { public function index(){return Pilot::withCount('flights')->latest()->paginate(15);} public function store(Request $r){$d=$r->validate(['full_name'=>'required|string|max:120','license_no'=>'required|string|max:50|unique:pilots','phone'=>'nullable|string|max:30','experience'=>'required|integer|min:0']);return response()->json(Pilot::create($d),201);} public function show(Pilot $pilot){return $pilot->load('flights');} public function update(Request $r,Pilot $pilot){$d=$r->validate(['full_name'=>'sometimes|required|string|max:120','license_no'=>'sometimes|required|string|max:50|unique:pilots,license_no,'.$pilot->id,'phone'=>'nullable|string|max:30','experience'=>'sometimes|required|integer|min:0']);$pilot->update($d);return $pilot->fresh();} public function destroy(Pilot $pilot){if($pilot->flights()->exists())return response()->json(['message'=>'این خلبان در پرواز ثبت‌شده استفاده شده است.'],409);$pilot->delete();return response()->json(['message'=>'خلبان حذف شد']);} }
